"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import { useEffect } from "react";

const customerSchema = z.object({
    name: z.string().min(3, "Nome deve ter pelo menos 3 caracteres"),
    doc: z.string().min(11, "Documento inválido"),
    email: z.string().email("E-mail inválido"),
    phone: z.string().min(8, "Telefone inválido"),
});

type CustomerFormData = z.infer<typeof customerSchema>;

interface CustomerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: CustomerFormData) => void;
    initialData?: any;
    title: string;
}

export default function CustomerModal({ isOpen, onClose, onSubmit, initialData, title }: CustomerModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        formState: { errors, isSubmitting }
    } = useForm<CustomerFormData>({
        resolver: zodResolver(customerSchema),
    });

    useEffect(() => {
        if (initialData) {
            reset(initialData);
        } else {
            reset({ name: "", doc: "", email: "", phone: "" });
        }
    }, [initialData, reset, isOpen]);

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <Input
                    label="Nome Completo / Razão Social"
                    {...register("name")}
                    error={errors.name?.message}
                    placeholder="Ex: João Silva ou Empresa LTDA"
                    helpText="Identificação clara agiliza o processo de emissão."
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input
                        label="CPF / CNPJ"
                        {...register("doc")}
                        error={errors.doc?.message}
                        placeholder="000.000.000-00"
                    />
                    <Input
                        label="Telefone WhatsApp"
                        {...register("phone")}
                        error={errors.phone?.message}
                        placeholder="(11) 99999-9999"
                        helpText="Lead com WhatsApp tem 40% mais conversão."
                    />
                </div>

                <Input
                    label="E-mail de Faturamento"
                    {...register("email")}
                    error={errors.email?.message}
                    placeholder="exemplo@email.com"
                />

                <div className="flex flex-col-reverse md:flex-row justify-end gap-3 pt-6 border-t border-slate-50 dark:border-slate-800/50">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-2.5 rounded-lg font-bold text-xs text-[var(--muted)] hover:text-[var(--foreground)] transition-all"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="flex-1 max-w-full md:max-w-[60%] bg-primary text-on-primary px-8 py-3 rounded-lg font-bold text-sm shadow-sm hover:bg-primary/90 active:scale-95 transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? "Salvando..." : "Confirmar e Cadastrar"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
